import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Storage and Context Architecture","description":"Hearth SQLite, content blobs, executor directories, the unified model registry, and context handoff boundaries.","frontmatter":{"title":"Storage and Context Architecture","description":"Hearth SQLite, content blobs, executor directories, the unified model registry, and context handoff boundaries.","outline":[2]},"headers":[],"relativePath":"en/design/storage.md","filePath":"en/design/storage.md","lastUpdated":1794305977000}'),r={name:"en/design/storage.md"};function s(n,e,c,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="storage-and-context-architecture" tabindex="-1">Storage and Context Architecture <a class="header-anchor" href="#storage-and-context-architecture" aria-label="Permalink to &quot;Storage and Context Architecture&quot;">​</a></h1><p class="lead">Hearth separates rebuildable facts, body content, and working directories. SQLite is the single state index and event ledger; the filesystem holds large bodies, workspaces, and installed runtimes. Context, model bindings, and executor handoffs all recover from the same records.</p><h2 id="core-constraints" tabindex="-1">Core Constraints <a class="header-anchor" href="#core-constraints" aria-label="Permalink to &quot;Core Constraints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Constraint</th><th>Meaning</th></tr></thead><tbody><tr><td>One write authority</td><td>One server process writes SQLite; interfaces, notifications, and reports read projections instead of creating a second source of truth</td></tr><tr><td>Record before display</td><td>Tasks, runs, context, model bindings, and migration results are stored first and then pushed to the browser over SSE</td></tr><tr><td>Indexes separate from bodies</td><td>The database stores metadata, summaries, hashes, and references; large text goes to content blobs and deliverables stay in task workspaces</td></tr><tr><td>Every run is traceable</td><td>A context item carries <code>task_id</code>, <code>run_id</code>, <code>executor_id</code>, <code>provenance_json</code>, and a stable <code>executor_event_id</code></td></tr><tr><td>Executors do not hold long-lived credentials</td><td>Model keys are encrypted with AES-256-GCM in the database; an executor gets decrypted configuration only for its run</td></tr></tbody></table><p>The current database schema version is <strong>28</strong>. At startup, <code>packages/eventlog/src/database.ts</code> runs table creation and incremental migrations in order, then writes <code>PRAGMA user_version</code> and <code>app_meta.schemaVersion</code>.</p><h2 id="the-hearth-directory" tabindex="-1">The <code>.hearth</code> Directory <a class="header-anchor" href="#the-hearth-directory" aria-label="Permalink to &quot;The \`.hearth\` Directory&quot;">​</a></h2><p>The default data directory is <code>.hearth/</code> under the repository root and can be overridden with <code>HEARTH_DATA_DIR</code>.</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th><th>Included in a database backup</th></tr></thead><tbody><tr><td><code>.hearth/hearth.sqlite</code></td><td>Events, tasks, runs, approvals, effects, context indexes, model profiles, settings, and migrations</td><td>Yes</td></tr><tr><td><code>.hearth/master.key</code></td><td>Local encryption master key for model API keys and similar sensitive fields</td><td>Yes, encrypted again under the backup passphrase</td></tr><tr><td><code>.hearth/context/blobs/</code></td><td>Context bodies above the inline threshold, named by content SHA-256</td><td>No</td></tr><tr><td><code>.hearth/workspaces/tasks/&lt;taskId&gt;/</code></td><td>A task workspace, inputs, outputs, and <code>.hearth</code> checkpoints</td><td>No</td></tr><tr><td><code>.hearth/artifacts/</code></td><td>Managed deliverables and manifests</td><td>No</td></tr><tr><td><code>.hearth/sources/</code></td><td>Fetched or imported source bodies</td><td>No</td></tr><tr><td><code>.hearth/attachments/</code></td><td>Chat attachments</td><td>No</td></tr><tr><td><code>.hearth/outbox/</code></td><td>Local outbox drafts and receipt files</td><td>No</td></tr><tr><td><code>.hearth/executors/codex/</code></td><td>Codex <code>config.toml</code> generated from the unified binding, plus its runtime directory</td><td>No</td></tr><tr><td><code>.hearth/executors/deepseek-harness/</code></td><td>DeepSeek Harness provider patch and session runtime directory</td><td>No</td></tr><tr><td><code>.hearth/executors/&lt;id&gt;/</code></td><td>Managed installations and runtime directories for other external executors</td><td>No</td></tr><tr><td><code>.hearth/backups/</code></td><td>AES-256-GCM encrypted database backup archives</td><td>-</td></tr><tr><td><code>.hearth/backups/legacy-dev/</code></td><td>Original copies retained during the first JSON settings migration</td><td>-</td></tr><tr><td><code>.hearth/device-frames/</code></td><td>Desktop observation frame cache</td><td>No</td></tr><tr><td><code>.hearth/git-cache/</code></td><td>Repository preparation cache</td><td>No</td></tr></tbody></table><p><code>model-settings.json</code> and <code>executor-settings.json</code> are retained only as legacy migration sources and are no longer written by Settings. A successful migration does not delete the originals, preserving audit and rollback value.</p><h2 id="sqlite-domains" tabindex="-1">SQLite Domains <a class="header-anchor" href="#sqlite-domains" aria-label="Permalink to &quot;SQLite Domains&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain</th><th>Main tables</th><th>Purpose</th></tr></thead><tbody><tr><td>Event ledger</td><td><code>events</code></td><td>Append-only fact stream that drives SSE, sync, and projection rebuilds</td></tr><tr><td>Goals and completion</td><td><code>goals</code>, <code>goal_completion_reports</code>, <code>prepared_actions</code></td><td>Goal contracts, acceptance evidence, verdicts, and prepared-action previews</td></tr><tr><td>Tasks and runs</td><td><code>tasks</code>, <code>runs</code>, <code>task_follow_ups</code>, <code>run_checkpoints</code>, <code>task_proposals</code></td><td>Task state machine, follow-up input, attempts, budgets, and recovery points</td></tr><tr><td>Conversations</td><td><code>conversations</code>, <code>chat_messages</code></td><td>Chat messages and upsertable <code>task_status</code> cards</td></tr><tr><td>Approvals and effects</td><td><code>approvals</code>, <code>effects</code>, <code>reconcile_queue</code>, <code>outbox_drafts</code></td><td>One-time authority, idempotent execution, uncertain-effect reconciliation, and external receipts</td></tr><tr><td>Artifacts and sources</td><td><code>artifacts</code>, <code>sources</code>, <code>source_items</code></td><td>Deliverable indexes, source body indexes, and fetch records</td></tr><tr><td>Delegation and task graph</td><td><code>delegation_jobs</code>, <code>handoffs</code>, <code>task_edges</code></td><td>Single-layer delegation, executor handoff, and dependency/join edges</td></tr><tr><td>Context</td><td><code>context_items</code>, <code>task_context_state</code>, <code>context_settings</code></td><td>Execution trail, task summary, and context policy</td></tr><tr><td>Context packs</td><td><code>context_packs</code>, <code>context_pack_items</code>, <code>memory_entities</code></td><td>Channeled context, budgets, references, and memory-entity links</td></tr><tr><td>Model management</td><td><code>model_profiles</code>, <code>executor_model_bindings</code>, <code>app_settings</code></td><td>Unified model profiles, executor bindings, and chat model selection</td></tr><tr><td>Settings migration</td><td><code>settings_migrations</code></td><td>Legacy JSON source, backup path, status, and error</td></tr><tr><td>Personal context</td><td><code>entities</code>, <code>entity_aliases</code>, <code>relations</code>, <code>entity_states</code>, <code>decisions</code>, <code>commitments</code>, <code>mentions</code></td><td>Personal ontology, states, decisions, commitments, and mention evidence</td></tr><tr><td>Memory and methods</td><td><code>memories</code>, <code>memory_*</code>, <code>method_*</code>, <code>method_applications</code>, <code>skills</code>, <code>skill_*</code></td><td>Correctable memory, recall audit, method evolution, and skill lifecycle</td></tr><tr><td>Attention</td><td><code>standing_intents</code>, <code>attention_items</code>, <code>heartbeat_runs</code>, <code>attention_feedback</code></td><td>Standing intents, heartbeat, candidates, budgets, and user feedback</td></tr><tr><td>Multi-device and security</td><td><code>devices</code>, <code>pairing_requests</code>, <code>sync_*</code>, <code>task_leases</code>, <code>connection_*</code>, <code>channel_*</code></td><td>Pairing, sync, leases, connection runtime, offline outbox, and channel idempotency</td></tr><tr><td>Operations</td><td><code>maintenance_runs</code>, <code>backup_records</code>, <code>scheduled_jobs</code>, <code>scheduled_job_runs</code>, <code>watchdog_events</code></td><td>Maintenance, backups, periodic jobs, catch-up, cooldown, and watchdog records</td></tr></tbody></table><p>Method applications are append-only local audit records; they are not replayed as events or synchronized across devices. <code>tasks.method_id/method_version</code> pins an explicit binding, while <code>method_applications</code> records the method version, selection mode, and prompt hash actually injected in each run. <code>method_candidates.generation</code> identifies the adoption generation and <code>fingerprint</code> deduplicates deterministic candidate creation.</p><h2 id="unified-model-registry" tabindex="-1">Unified Model Registry <a class="header-anchor" href="#unified-model-registry" aria-label="Permalink to &quot;Unified Model Registry&quot;">​</a></h2><p>Models are no longer stored in an executor-specific JSON file. The registry has two layers:</p><ol><li><strong>Model profile <code>model_profiles</code></strong>: display name, provider, protocol, base URL, model name, and encrypted API key.</li><li><strong>Executor binding <code>executor_model_bindings</code></strong>: chooses a profile for each executor and permits constrained protocol or model overrides.</li></ol><p><code>app_settings.model.chatProfileId</code> stores the current Hearth chat model. It serves chat, failure diagnosis, and the native executor. An external executor uses its own binding only when that binding is valid.</p><p>The server enforces protocol compatibility:</p><table tabindex="0"><thead><tr><th>Executor</th><th>Allowed protocols</th></tr></thead><tbody><tr><td><code>native</code></td><td><code>openai-chat</code>, <code>openai-responses</code>, <code>anthropic-messages</code>, <code>gemini</code></td></tr><tr><td><code>codex</code></td><td><code>openai-responses</code> only</td></tr><tr><td><code>deepseek-harness</code></td><td><code>openai-chat</code>, <code>openai-responses</code>, <code>anthropic-messages</code></td></tr><tr><td><code>hermes</code>, <code>qoder</code>, <code>workbuddy</code>, <code>kimi</code></td><td><code>openai-chat</code>, <code>openai-responses</code>, <code>anthropic-messages</code></td></tr></tbody></table><p>The Codex binding generates a dedicated <code>.hearth/executors/codex/config.toml</code> with <code>wire_api = &quot;responses&quot;</code> and injects the key through the process environment. Local addresses (<code>localhost</code>, <code>127.0.0.1</code>, private ranges, and <code>.local</code>) are excluded from the unified registry so a local model is not mistaken for a cloud profile.</p><h2 id="context-lifecycle" tabindex="-1">Context Lifecycle <a class="header-anchor" href="#context-lifecycle" aria-label="Permalink to &quot;Context Lifecycle&quot;">​</a></h2><p>Context is a task-level record shared by every executor; it does not depend on a CLI&#39;s private session.</p><ol><li><strong>Capture</strong>: the native runtime, Codex, DeepSeek Harness, and external CLIs normalize messages, tool calls, tool results, checkpoints, and notices into <code>ContextItem</code> records.</li><li><strong>Deduplicate</strong>: <code>executor_event_id</code> is unique within a run, so repeated notifications do not duplicate rows.</li><li><strong>Inline or blob</strong>: when a body exceeds <code>maxInlineBytes</code>, Hearth writes <code>.hearth/context/blobs/&lt;sha256&gt;.txt</code>; the database keeps <code>content_ref</code>, <code>sha256</code>, and a truncated inline excerpt.</li><li><strong>Summarize</strong>: after items pass <code>summarizeAfterTokens</code>, <code>task_context_state</code> is refreshed with the goal, plan, completed work, failures, artifacts, and open questions.</li><li><strong>Project</strong>: when an executor starts or takes over, Hearth generates a context projection bounded by <code>projectionTokenBudget</code> instead of sending the full history to the CLI.</li><li><strong>Handoff</strong>: <code>handoffs</code> stores the diagnosis, packet, source and target runs, and <code>context_watermark_seq</code>; the takeover executor continues from the same watermark so late results cannot overwrite newer state.</li><li><strong>Delete</strong>: deleting task context removes <code>context_items</code>, <code>task_context_state</code>, and blobs with no remaining references; content still referenced by another task is retained.</li></ol><p>Context modes are <code>off</code>, <code>shadow</code>, and <code>on</code>. <code>shadow</code> records without injecting and is useful for validating capture quality; <code>on</code> projects context into execution and handoff. Defaults are two handoffs, one retry per executor, and 30-day retention.</p><h2 id="startup-migration" tabindex="-1">Startup Migration <a class="header-anchor" href="#startup-migration" aria-label="Permalink to &quot;Startup Migration&quot;">​</a></h2><p>The server handles legacy settings in this order:</p><ol><li>Read <code>.hearth/model-settings.json</code> and <code>.hearth/executor-settings.json</code>.</li><li>Copy the originals into <code>.hearth/backups/legacy-dev/</code> with a time or migration identifier.</li><li>Write <code>model_profiles</code>, <code>executor_model_bindings</code>, and <code>app_settings</code> in a transaction.</li><li>Record <code>legacy-model-settings-v1</code> and <code>legacy-executor-settings-v1</code> in <code>settings_migrations</code> with source, backup, status, and error.</li><li>If any step fails, roll back database writes while retaining the backup and failure record; the server does not start in a half-migrated state.</li></ol><p>Migration is idempotent: completed IDs are not imported twice, and an existing profile with the same provider, URL, model, and protocol is reused instead of duplicated.</p><h2 id="backup-and-restore-boundaries" tabindex="-1">Backup and Restore Boundaries <a class="header-anchor" href="#backup-and-restore-boundaries" aria-label="Permalink to &quot;Backup and Restore Boundaries&quot;">​</a></h2><p>A database backup contains the SQLite snapshot, schema version, table counts, and the local <code>master.key</code>, all encrypted with AES-256-GCM under a key derived from the user passphrase. Restore verifies that the source schema is not newer than the current version, the payload hash matches, and the candidate database passes <code>PRAGMA integrity_check</code> before replacing the live database.</p><p>The backup <strong>does not include</strong> context blobs, task workspaces, artifact bodies, source bodies, attachments, or outbox files. For a complete migration, copy these paths as well:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.hearth/context/blobs/</span></span>
<span class="line"><span>.hearth/workspaces/</span></span>
<span class="line"><span>.hearth/artifacts/</span></span>
<span class="line"><span>.hearth/sources/</span></span>
<span class="line"><span>.hearth/attachments/</span></span>
<span class="line"><span>.hearth/outbox/</span></span></code></pre></div><h2 id="operational-checks" tabindex="-1">Operational Checks <a class="header-anchor" href="#operational-checks" aria-label="Permalink to &quot;Operational Checks&quot;">​</a></h2><p>The Data section in Settings shows the database path, schema version, executor directories, context blob directory, migration records, and legacy JSON sources. When diagnosing a problem, inspect:</p><ul><li><code>settings_migrations</code>: whether legacy settings imported successfully and why they failed.</li><li><code>model_profiles</code> and <code>executor_model_bindings</code>: whether an executor has a protocol-compatible profile with a key.</li><li><code>context_items</code> and <code>task_context_state</code>: whether the task captured its execution trail and advanced its summary watermark.</li><li><code>handoffs</code>: whether the target, diagnosis, and context watermark agree.</li><li><code>backup_records</code>: whether the latest backup succeeded and restore passed integrity checks.</li></ul><p>Database records are authoritative. Do not hand-edit <code>model-settings.json</code> or <code>executor-settings.json</code> to change runtime configuration.</p>`,35)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
